#include <array>
#include <cstdio>
#include <iostream>

int main()
{
    char s[51];
    if (std::scanf("%50s", s) != 1) return 0;

    int n = 0;
    std::array<int, 50> v{};
    while (s[n]) {
        v[n] = s[n] - '0';
        ++n;
    }

    long long dp[10][2] = {};
    for (int digit = 0; digit < 10; ++digit)
        dp[digit][digit != v[0]] = 1;

    for (int i = 1; i < n; ++i) {
        long long next[10][2] = {};

        for (int previous = 0; previous < 10; ++previous) {
            for (int different = 0; different < 2; ++different) {
                const long long count = dp[previous][different];
                if (count == 0) continue;

                const int sum = v[i] + previous;
                const int low = sum / 2;
                next[low][different || low != v[i]] += count;

                if (sum % 2 != 0) {
                    const int high = low + 1;
                    next[high][different || high != v[i]] += count;
                }
            }
        }

        for (int digit = 0; digit < 10; ++digit)
            for (int different = 0; different < 2; ++different)
                dp[digit][different] = next[digit][different];
    }

    long long result = 0;
    for (int digit = 0; digit < 10; ++digit)
        result += dp[digit][1];

    std::cout << result << '\n';
    return 0;
}

