#include <cstdio>
#include <cstring>
#include <iostream>

int v[50];
long long memo[51][10][2];

long long search(int i, int n, int previous, bool different)
{
    if (i == n) return different;

    long long &result = memo[i][previous][different];
    if (result != -1) return result;

    result = 0;
    int sum = v[i] + previous;
    int digit = sum / 2;

    result += search(i + 1, n, digit, different || digit != v[i]);

    if (sum % 2 != 0) {
        ++digit;
        result += search(i + 1, n, digit, different || digit != v[i]);
    }

    return result;
}

int main()
{
    char s[51];
    if (std::scanf("%50s", s) != 1) return 0;

    int n = 0;
    while (s[n]) {
        v[n] = s[n] - '0';
        ++n;
    }

    std::memset(memo, -1, sizeof(memo));

    long long result = 0;
    for (int digit = 0; digit < 10; ++digit) {
        result += search(1, n, digit, digit != v[0]);
    }

    std::cout << result << '\n';
    return 0;
}

